def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and s[j].isalnum():
                    j += 1
                word = s[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FN", word))
                else:
                    tokens.append(("CELL", word))
                i = j
            elif ch in "<>":
                if i + 1 < n and s[i : i + 2] in ("<>", "<=", ">="):
                    tokens.append(("OP", s[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", ch))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            elif ch in "+-*/(),:":
                tokens.append((ch, ch))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {ch}")
        return tokens

    def parse_range(c1: str, c2: str) -> tuple[int, int, int, int]:
        col1, row1 = ord(c1[0]) - 65, int(c1[1:])
        col2, row2 = ord(c2[0]) - 65, int(c2[1:])
        if col1 > col2:
            col1, col2 = col2, col1
        if row1 > row2:
            row1, row2 = row2, row1
        return (row1, row2, col1, col2)

    def parse(tokens: list[tuple[str, object]]) -> tuple:
        pos = 0
        n = len(tokens)

        def peek() -> tuple[str | None, object]:
            return tokens[pos] if pos < n else (None, None)

        def consume(expected: str | None = None) -> tuple[str, object]:
            nonlocal pos
            tok = tokens[pos]
            if expected is not None and tok[0] != expected:
                raise ValueError(f"Expected {expected}, got {tok}")
            pos += 1
            return tok

        def parse_expr() -> tuple:
            node = parse_term()
            while peek()[0] in ("+", "-"):
                op = consume()[0]
                right = parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term() -> tuple:
            node = parse_unary()
            while peek()[0] in ("*", "/"):
                op = consume()[0]
                right = parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary() -> tuple:
            if peek()[0] == "-":
                consume()
                return ("NEG", parse_unary())
            return parse_atom()

        def parse_atom() -> tuple:
            ttype, tval = peek()
            if ttype == "NUM":
                consume()
                return ("NUM", tval)
            if ttype == "CELL":
                consume()
                return ("CELL", tval)
            if ttype == "(":
                consume()
                node = parse_expr()
                consume(")")
                return node
            if ttype == "FN":
                fn = consume()[1]
                consume("(")
                if fn == "IF":
                    left = parse_expr()
                    op = consume("OP")[1]
                    right = parse_expr()
                    consume(",")
                    then_expr = parse_expr()
                    consume(",")
                    else_expr = parse_expr()
                    consume(")")
                    return ("IF", op, left, right, then_expr, else_expr)
                args = []
                while True:
                    if (
                        peek()[0] == "CELL"
                        and pos + 1 < n
                        and tokens[pos + 1][0] == ":"
                    ):
                        c1 = str(consume("CELL")[1])
                        consume(":")
                        c2 = str(consume("CELL")[1])
                        args.append(("RANGE", parse_range(c1, c2)))
                    else:
                        args.append(parse_expr())
                    if peek()[0] == ",":
                        consume()
                    else:
                        break
                consume(")")
                return ("AGG", fn, args)
            raise ValueError(f"Unexpected token: {ttype} {tval}")

        return parse_expr()

    memo: dict[str, int | str] = {}
    parsed: dict[str, tuple] = {}
    for name, content in cells.items():
        if content.startswith("="):
            parsed[name] = parse(tokenize(content[1:]))
        else:
            memo[name] = int(content)

    visiting: set[str] = set()
    stack: list[tuple] = []
    vals: list[int | str] = []

    def push_cell(name: str) -> None:
        if name not in cells:
            vals.append(0)
        elif name in memo:
            vals.append(memo[name])
        elif name in visiting:
            vals.append("#CYCLE!")
        else:
            visiting.add(name)
            stack.append(("CELL_DONE", name))
            stack.append(("EVAL", parsed[name]))

    for start in cells:
        if start in memo:
            continue
        push_cell(start)
        while stack:
            frame = stack.pop()
            tag = frame[0]

            if tag == "EVAL":
                node = frame[1]
                kind = node[0]
                if kind == "NUM":
                    vals.append(node[1])
                elif kind == "CELL":
                    push_cell(node[1])
                elif kind == "NEG":
                    stack.append(("NEG_DONE",))
                    stack.append(("EVAL", node[1]))
                elif kind == "BIN":
                    stack.append(("BIN_LEFT", node[1], node[3]))
                    stack.append(("EVAL", node[2]))
                elif kind == "IF":
                    stack.append(("IF_LEFT", node[1], node[3], node[4], node[5]))
                    stack.append(("EVAL", node[2]))
                elif kind == "AGG":
                    stack.append(("AGG_STEP", node[1], node[2], 0, None, None, 0, False))

            elif tag == "CELL_DONE":
                name = frame[1]
                visiting.remove(name)
                memo[name] = vals[-1]

            elif tag == "NEG_DONE":
                v = vals.pop()
                vals.append(v if isinstance(v, str) else -v)

            elif tag == "BIN_LEFT":
                _, op, right = frame
                v = vals.pop()
                if isinstance(v, str):
                    vals.append(v)
                else:
                    stack.append(("BIN_RIGHT", op, v))
                    stack.append(("EVAL", right))

            elif tag == "BIN_RIGHT":
                _, op, left_val = frame
                right_val = vals.pop()
                if isinstance(right_val, str):
                    vals.append(right_val)
                elif op == "+":
                    vals.append(left_val + right_val)
                elif op == "-":
                    vals.append(left_val - right_val)
                elif op == "*":
                    vals.append(left_val * right_val)
                else:
                    if right_val == 0:
                        vals.append("#DIV/0!")
                    else:
                        q = abs(left_val) // abs(right_val)
                        vals.append(-q if (left_val < 0) ^ (right_val < 0) else q)

            elif tag == "IF_LEFT":
                _, op, right, then_expr, else_expr = frame
                left_val = vals.pop()
                if isinstance(left_val, str):
                    vals.append(left_val)
                else:
                    stack.append(("IF_RIGHT", op, left_val, then_expr, else_expr))
                    stack.append(("EVAL", right))

            elif tag == "IF_RIGHT":
                _, op, left_val, then_expr, else_expr = frame
                right_val = vals.pop()
                if isinstance(right_val, str):
                    vals.append(right_val)
                else:
                    if op == "=":
                        cond = left_val == right_val
                    elif op == "<>":
                        cond = left_val != right_val
                    elif op == "<":
                        cond = left_val < right_val
                    elif op == "<=":
                        cond = left_val <= right_val
                    elif op == ">":
                        cond = left_val > right_val
                    else:
                        cond = left_val >= right_val
                    stack.append(("EVAL", then_expr if cond else else_expr))

            elif tag == "AGG_STEP":
                _, fn, args, arg_idx, cur_r, cur_c, acc, has_val = frame
                if arg_idx == len(args):
                    vals.append(acc if has_val else 0)
                else:
                    arg = args[arg_idx]
                    if arg[0] == "RANGE":
                        r1, r2, c1, c2 = arg[1]
                        if cur_r is None:
                            cur_r, cur_c = r1, c1
                        found = None
                        while cur_r <= r2:
                            cname = f"{chr(65 + cur_c)}{cur_r}"
                            cur_c += 1
                            if cur_c > c2:
                                cur_c = c1
                                cur_r += 1
                            if cname in cells:
                                found = cname
                                break
                        if found is None:
                            stack.append(
                                ("AGG_STEP", fn, args, arg_idx + 1, None, None, acc, has_val)
                            )
                        else:
                            stack.append(
                                ("AGG_VAL", fn, args, arg_idx, cur_r, cur_c, acc, has_val)
                            )
                            push_cell(found)
                    else:
                        stack.append(
                            ("AGG_VAL", fn, args, arg_idx + 1, None, None, acc, has_val)
                        )
                        stack.append(("EVAL", arg))

            elif tag == "AGG_VAL":
                _, fn, args, next_idx, next_r, next_c, acc, has_val = frame
                v = vals.pop()
                if isinstance(v, str):
                    vals.append(v)
                else:
                    if not has_val:
                        acc = v
                        has_val = True
                    elif fn == "SUM":
                        acc += v
                    elif fn == "MIN":
                        if v < acc:
                            acc = v
                    else:
                        if v > acc:
                            acc = v
                    stack.append(
                        ("AGG_STEP", fn, args, next_idx, next_r, next_c, acc, has_val)
                    )

        vals.pop()

    return {k: memo[k] for k in cells}
